// Offload CPU-heavy work to a worker pool (piscina) instead of blocking the loop
import Piscina from "piscina";

const pool = new Piscina({ filename: new URL("./hash-worker.js", import.meta.url).href, maxThreads: 4 });

app.post("/thumbnail", async (req, res) => {
  const out = await pool.run({ bytes: req.body }); // runs on another thread; the loop stays free
  res.type("image/webp").send(out);
});

// Streaming a large file with backpressure and proper error handling
import { createReadStream } from "node:fs";
import { createGzip } from "node:zlib";
import { pipeline } from "node:stream/promises";

app.get("/export.csv.gz", async (req, res) => {
  res.setHeader("Content-Type", "application/gzip");
  await pipeline(createReadStream("export.csv"), createGzip(), res); // constant memory
});

// Measuring event-loop delay
import { monitorEventLoopDelay } from "node:perf_hooks";
const h = monitorEventLoopDelay({ resolution: 20 });
h.enable();
setInterval(() => { console.log("p99 loop delay ms", h.percentile(99) / 1e6); h.reset(); }, 10_000).unref();

