// A small, well-layered Express app: validation, services, central error handling
import express from "express";
import { z } from "zod";
import pino from "pino";
import { randomUUID } from "node:crypto";

const log = pino({ redact: ["req.headers.authorization", "*.password"] });

class AppError extends Error {
  constructor(public status: number, public code: string, msg: string) { super(msg); }
}

const placeOrder = z.object({ sku: z.string().min(1), qty: z.number().int().min(1).max(100) }).strict(); // .strict() = no extra keys

export function buildApp(deps: { orders: ReturnType<typeof makeOrderService> }) {
  const app = express();
  app.use(express.json({ limit: "100kb" }));                         // bounded body
  app.use((req, res, next) => {                                      // request id + access log
    const id = (req.headers["x-request-id"] as string) ?? randomUUID();
    res.setHeader("x-request-id", id);
    Object.assign(req, { id });
    const start = performance.now();
    res.on("finish", () => log.info({ reqId: id, method: req.method, url: req.originalUrl, status: res.statusCode, ms: Math.round(performance.now() - start) }));
    next();
  });

  app.post("/v1/orders", async (req, res) => {
    const input = placeOrder.parse(req.body);                         // throws ZodError -> handler
    const order = await deps.orders.place(input);                     // service: no req/res inside
    res.status(201).location(`/v1/orders/${order.id}`).json(order);
  });

  // central error handler: LAST middleware
  app.use((err: unknown, req: express.Request, res: express.Response, _next: express.NextFunction) => {
    const reqId = (req as any).id;
    if (err instanceof z.ZodError) return res.status(422).json({ code: "validation_failed", errors: err.issues, reqId });
    if (err instanceof AppError) return res.status(err.status).json({ code: err.code, message: err.message, reqId });
    log.error({ err, reqId }, "unhandled");                           // full detail in logs only
    res.status(500).json({ code: "internal", message: "Something went wrong", reqId });
  });
  return app;
}

// Graceful shutdown + process safety nets
const server = app.listen(port);
let ready = true;
app.get("/readyz", (_req, res) => (ready ? res.sendStatus(200) : res.sendStatus(503)));

async function shutdown(signal: string) {
  log.info({ signal }, "shutting down");
  ready = false;                                   // load balancer stops routing here
  server.close(async () => {                       // stops accepting; waits for in-flight requests
    await Promise.allSettled([db.end(), redis.quit()]);
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => process.exit(1), 25_000).unref(); // hard deadline below the platform's kill timeout
}
process.on("SIGTERM", () => shutdown("SIGTERM"));
process.on("SIGINT", () => shutdown("SIGINT"));
process.on("unhandledRejection", (e) => { log.fatal({ e }, "unhandledRejection"); process.exit(1); });
